    var ss=d.srcset||d.lazySrcset||el.getAttribute('data-lazy-srcset');
    if(ss&&!el.getAttribute('srcset'))el.setAttribute('srcset',ss);
    el.removeAttribute('loading');
    var ps=d.poster||el.getAttribute('data-lazy-poster');
    if(ps&&!el.getAttribute('poster'))el.setAttribute('poster',ps);
    if(el.tagName==='VIDEO'){
      /* iOS speelt alleen inline en gedempt; zonder metadata blijft het vlak leeg. */
      el.muted=true; el.defaultMuted=true; el.setAttribute('muted','');
      el.setAttribute('playsinline',''); el.setAttribute('webkit-playsinline','');
      if(el.getAttribute('preload')==='none')el.setAttribute('preload','metadata');
    }
  });

  /* Vangnet: laadt een plaatje niet, dan één keer opnieuw proberen. */
  root.querySelectorAll('img').forEach(function(img){
    img.addEventListener('error',function(){
      if(img.dataset.dpvRetry)return; img.dataset.dpvRetry='1';
      var s=img.getAttribute('src')||'';
      if(s)img.setAttribute('src',s+(s.indexOf('?')>-1?'&':'?')+'dpv=1');
    });
  });



  /* Community-carrousel: drie in beeld, alleen de middelste is actief.
     Video's laden pas als je op play tikt — dat houdt de pagina snel. */
  var box=root.querySelector('[data-dpv-com-grid]');
  if(box){
    var all=[].slice.call(box.children),i=1;
    var paint=function(){
      var mob=window.innerWidth<=860;
      var order=[(i+all.length-1)%all.length,i,(i+1)%all.length];
      all.forEach(function(el,n){
        var pos=order.indexOf(n);
        el.style.display=(mob||pos>-1)?'':'none';
        el.dataset.active=(!mob&&pos===1)?'true':'false';
        var v=el.querySelector('video');
        if(v){
          var btn=el.querySelector('[data-dpv-play]');
          if(!mob&&pos===1){
            /* midden: laden en spelen */
            if(v.getAttribute('preload')!=='auto'){v.setAttribute('preload','auto');v.load();}
            var p=v.play();
            if(p&&p.catch)p.catch(function(){});
            if(btn){btn.textContent='❚❚';btn.dataset.paused='false';btn.setAttribute('aria-label','Video pauzeren');}
