            /* zijkant: alleen het eerste frame, niets meer downloaden */
            v.pause();
            if(btn){btn.textContent='▶';btn.dataset.paused='true';btn.setAttribute('aria-label','Video afspelen');}
          }
        }
      });
      if(!mob)order.forEach(function(n){box.appendChild(all[n]);});
    };

    /* Mobiel: geen carrousel maar een swipe-rij. Video's halen hun eerste frame
       op zodra ze in beeld komen, zodat er geen leeg vlak staat. */
    if(window.IntersectionObserver){
