    });
    root.querySelectorAll('[data-dpv-play]').forEach(function(btn){
      btn.addEventListener('click',function(){
        var v=btn.parentNode.querySelector('video');
        if(!v)return;
        if(v.paused){
          if(v.getAttribute('preload')!=='auto'){v.setAttribute('preload','auto');v.load();}
